<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { systemApi, type DataScope, type Department, type Permission, type Role } from '@/api/system'
const rows=ref<Role[]>([]),permissions=ref<Permission[]>([]),departments=ref<Department[]>([]),visible=ref(false),loading=ref(false),editingId=ref<number|null>(null)
const form=reactive({code:'',name:'',status:'ENABLED',version:0,permissionIds:[] as number[],scopeType:'ALL',deptIds:[] as number[]})
async function load(){loading.value=true;try{[rows.value,permissions.value,departments.value]=await Promise.all([systemApi.roles(),systemApi.permissions(),systemApi.departments()])}finally{loading.value=false}}
function create(){editingId.value=null;Object.assign(form,{code:'',name:'',status:'ENABLED',version:0,permissionIds:[],scopeType:'ALL',deptIds:[]});visible.value=true}
async function edit(row:Role){editingId.value=row.id;const [ids,scopes]=await Promise.all([systemApi.rolePermissions(row.id),systemApi.roleScopes(row.id)]);Object.assign(form,{code:row.code,name:row.name,status:row.status,version:row.version,permissionIds:ids,scopeType:scopes[0]?.scopeType||'ALL',deptIds:scopes.filter(s=>s.deptId).map(s=>s.deptId!) });visible.value=true}
function scopes():DataScope[]{return form.scopeType==='CUSTOM'?form.deptIds.map(deptId=>({scopeType:'CUSTOM',deptId})):[{scopeType:form.scopeType,deptId:null}]}
async function save(){const data={code:form.code,name:form.name,status:form.status,version:form.version,permissionIds:form.permissionIds,dataScopes:scopes()};if(editingId.value)await systemApi.updateRole(editingId.value,data);else await systemApi.createRole(data);visible.value=false;ElMessage.success('角色已保存');await load()}
async function remove(row:Role){await ElMessageBox.confirm(`确定删除角色“${row.name}”吗？`,'删除确认',{type:'warning'});await systemApi.deleteRole(row.id);ElMessage.success('已删除');await load()}
onMounted(load)
</script>
<template><section><div class="page-heading"><div><p>RBAC</p><h1>角色权限</h1></div><el-button type="primary" @click="create">新增角色</el-button></div><div class="content-card"><el-table v-loading="loading" :data="rows"><el-table-column prop="code" label="角色编码"/><el-table-column prop="name" label="角色名称"/><el-table-column prop="userCount" label="用户数"/><el-table-column prop="permissionCount" label="权限数"/><el-table-column label="状态"><template #default="s"><el-tag :type="s.row.status==='ENABLED'?'success':'info'">{{s.row.status==='ENABLED'?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column label="操作" width="215"><template #default="s"><div class="system-action-group"><el-button class="system-action system-config-action" @click="edit(s.row)">配置</el-button><el-button class="system-action system-delete-action" :disabled="s.row.builtIn" @click="remove(s.row)">删除</el-button></div></template></el-table-column></el-table></div>
<el-dialog v-model="visible" :title="editingId?'配置角色':'新增角色'" width="720px"><el-form label-width="90px"><el-form-item label="角色编码"><el-input v-model="form.code"/></el-form-item><el-form-item label="角色名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="状态"><el-radio-group v-model="form.status"><el-radio value="ENABLED">启用</el-radio><el-radio value="DISABLED">停用</el-radio></el-radio-group></el-form-item><el-form-item label="功能权限"><el-select v-model="form.permissionIds" multiple filterable collapse-tags collapse-tags-tooltip style="width:100%"><el-option v-for="p in permissions" :key="p.id" :label="`${p.name}（${p.code}）`" :value="p.id"/></el-select></el-form-item><el-form-item label="数据范围"><el-select v-model="form.scopeType" style="width:100%"><el-option label="全部数据" value="ALL"/><el-option label="本部门及下级" value="DEPT_AND_CHILDREN"/><el-option label="本部门" value="DEPT"/><el-option label="仅本人" value="SELF"/><el-option label="指定部门" value="CUSTOM"/></el-select></el-form-item><el-form-item v-if="form.scopeType==='CUSTOM'" label="指定部门"><el-select v-model="form.deptIds" multiple style="width:100%"><el-option v-for="d in departments" :key="d.id" :label="d.name" :value="d.id"/></el-select></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></section></template>
